1559	            const int last_pg = np ? 0 : ((t.seqlen_k - 1) / block_size);
1560	            const int ybase = np ? (cu_k ? cu_k[bi] : 0) : 0;         // non-paged: absolute key row of req bi
1561	            const int xk = t.hk * HD, xv = t.hk * HDV;
1562	            // load absolute key-tile nb into ring stage (gg % STAGES); pt==0 issues the TMA boxes.
1563	            // empty-gate on the GLOBAL gg keeps the ring a single continuous stream across items.
1564	            auto load_kv = [&](int gg, int nb) {
1565	                const int st = gg % STAGES;
1566	                if (gg >= STAGES) { int ep = ((gg / STAGES) - 1) & 1; while (!mbar_try_wait(&empty[st], ep)) {} }
1567	                TC* sKp = sK0 + st * KSTRIDE;
1568	                TC* sVp = sV0 + st * VSTRIDE;
1569	                mbar_expect_tx(&full[st], kv_bytes);
1570	                if (np) {
1571	                    // contiguous (non-paged): ONE [CN,64] box per col-block (same swizzled layout as paged).
1572	                    const int yk = ybase + nb * CN;
1573	#pragma unroll
1574	                    for (int bx = 0; bx < KBOX; ++bx) tma_box(sKp + bx * CB, &mapK, xk + bx * 64, yk, &full[st]);
1575	#pragma unroll
1576	                    for (int bx = 0; bx < VBOX; ++bx) tma_box(sVp + bx * CB, &mapV, xv + bx * 64, yk, &full[st]);
1577	                } else {
1578	                    for (int p = 0; p < pages; ++p) {
1579	                        int pg = nb * pages + p; if (pg > last_pg) pg = last_pg;
1580	                        int yrow = page_table[(long)bi * page_stride + pg] * block_size;
1581	                        int boff = p * block_size * 64;
1582	#pragma unroll
1583	                        for (int bx = 0; bx < KBOX; ++bx) tma_box(sKp + boff + bx * CB, &mapK, xk + bx * 64, yrow, &full[st]);
1584	#pragma unroll
1585	                        for (int bx = 0; bx < VBOX; ++bx) tma_box(sVp + boff + bx * CB, &mapV, xv + bx * 64, yrow, &full[st]);
1586	                    }
1587	                }
1588	            };
1589	            // Non-TMA paged variant: all 128 producer lanes cooperate on the barrier-free spread gather
1590	            // (see prefill_kernel COOP). full[] is inited to NumProd for !USE_TMA, so each lane arrives via
1591	            // cp_async_mbar_arrive (PF_PUBLISH). HD==HDV==128 only (COOP invariant); other HD stay on TMA.
1592	            auto load_kv_coop = [&](int gg, int nb) {
1593	                const int st = gg % STAGES;
1594	                if (gg >= STAGES) { int ep = ((gg / STAGES) - 1) & 1; while (!mbar_try_wait(&empty[st], ep)) {} }
1595	                TC* sKp = sK0 + st * KSTRIDE; TC* sVp = sV0 + st * VSTRIDE;
1596	                const uint32_t sKa = (uint32_t)__cvta_generic_to_shared(sKp);
1597	                const uint32_t sVa = (uint32_t)__cvta_generic_to_shared(sVp);
1598	                int ent = -1;
1599	                if (col_th < RPT) {
1600	                    const int key = nb * CN + rowsub + col_th * RPP;
1601	                    const bool kv = key < t.seqlen_k;
1602	                    if (page_table) {
1603	                        int blk = kv ? page_table[(long)bi * page_stride + key / block_size] : -1;
1604	                        ent = kv ? blk * block_size + (key % block_size) : -1;
1605	                    } else {
1606	                        ent = kv ? (ybase + key) : -1;
1607	                    }
1608	                }
1609	#pragma unroll
1610	                for (int r = 0; r < RPT; ++r) {
1611	                    const int row = rowsub + r * RPP;
1612	                    const long krow = __shfl_sync(0xffffffffu, ent, rsw * TPR + r, 32);
1613	#pragma unroll
1614	                    for (int ki = 0; ki < KIT; ++ki) {
