1619	                            cp_async_16(sVa + (uint32_t)(ov * 2), V + krow * v_row + (long)t.hk * v_head + cc);
1620	                        } else {
1621	                            *reinterpret_cast<uint4*>(sKp + ok) = make_uint4(0, 0, 0, 0);
1622	                            *reinterpret_cast<uint4*>(sVp + ov) = make_uint4(0, 0, 0, 0);
1623	                        }
1624	                    }
