2652	        1, nullptr, nullptr, qd, kd, vd, ds_b, ds_h, s_aux, nullptr, stream)
2653	#define PF_DISPATCH(HD_, HDV_, ST_, CN_, CM_)                                                           \
2654	    do {                                                                                                \
2655	        bool extra = (softcap > 0.0) || (win_l >= 0) || (win_r >= 0);                                   \
