2660	    else if (hd == 96 && hdv == 96)   PF_DISPATCH(96, 96, WS_STAGES, 128, 128);
2661	    // hd128: the windowed (SWA) EXTRA mask path's extra live registers tip the wide CM=128/CN=128
2662	    // consumer into spill-RELOADS (NCU: local spillLD 4608 -> long_scoreboard 37%, vs gqa EXTRA=false
2663	    // spillLD 0). A narrow CN=64 halves the score-register footprint s[CN/2] -> no spill, and since the
2664	    // 256-wide window leaves the tensor pipe only ~31% utilized, the narrower QK wgmma is ~free while
2665	    // finer 64-key tiles waste less compute past the window edge. STAGES=4 (CN=64 smem fits 5; the
2666	    // window is only ~4 tiles, so a 4-deep K/V ring already covers it). Non-windowed hd128 keeps the
2667	    // wide CN=128 tile (its gap is compute/barrier overlap, not register pressure -- CN=64 regressed it).
2668	    else if (hd == 128 && hdv == 128) {
