2673	    // hd192 -> dv128 (FA3 flash_fwd_hdimdiff): QK over HD=192, PV over HDV=128 (acc_o[64]). The smaller
2674	    // V accumulator frees smem for a deeper STAGES=4 K/V ring at CN=64 (hd192/hdv192 is stuck at STAGES=3).
2675	    else if (hd == 192 && hdv == 128) PF_DISPATCH(192, 128, 4, 64, 128);
