516	                asm volatile("{\n.reg .pred p;\n setp.ne.b32 p, %66, 0;\n"
517	                "wgmma.mma_async.sync.aligned.m64n128k16.f32.f16.f16 " PF_ACC64 ",%64,%65,p,%67,%68,%69,%70;\n}\n"
518	                : PF_OUT64(s) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1),"n"(0),"n"(0));
519	            else
520	                asm volatile("{\n.reg .pred p;\n setp.ne.b32 p, %66, 0;\n"
521	                "wgmma.mma_async.sync.aligned.m64n128k16.f32.bf16.bf16 " PF_ACC64 ",%64,%65,p,%67,%68,%69,%70;\n}\n"
522	                : PF_OUT64(s) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1),"n"(0),"n"(0));
523	        }
524	    }
525	    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
526	}
527	// One 64-col output box: (CN/16)x m64n64k16 wgmma accumulating into acc[O..O+31] (O compile-time).
528	// NO fence/commit here -- pv_boxes wraps ALL boxes in ONE wgmma group (single fence + single commit) so
529	// the whole PV is a single in-flight group. That lets wgmma_wait1 leave the ENTIRE PV overlapping the
530	// softmax (FA3's 2-group QK/PV pipeline). Per-box commit (the old form) left only the LAST box in flight
531	// after wait1, so softmax overlapped just 1/N of the PV -> tensor pipe 35% vs FA3 56%.
532	template <typename T, int O, int N, int CN>
533	__device__ __forceinline__ void pv_box64_body(float (&acc)[N], const uint32_t (&P)[CN/4], uint64_t baseV) {
534	#pragma unroll
535	    for (int kb = 0; kb < CN / 16; ++kb) {
536	        uint64_t dB = desc_add(baseV, (uint32_t)v_doff(kb));
537	        if constexpr (is_f16<T>())
538	            asm volatile(
539	            "{\n.reg .pred p;\n setp.ne.b32 p, %37, 0;\n"
540	            "wgmma.mma_async.sync.aligned.m64n64k16.f32.f16.f16 " PF_ACC32 ",{%32,%33,%34,%35},%36,p,%38,%39,%40;\n}\n"
541	            : PF_OUT32(acc, O)
542	            : "r"(P[kb*4+0]),"r"(P[kb*4+1]),"r"(P[kb*4+2]),"r"(P[kb*4+3]),"l"(dB),"r"(1),"n"(1),"n"(1),"n"(1));
543	        else
544	            asm volatile(
545	            "{\n.reg .pred p;\n setp.ne.b32 p, %37, 0;\n"
546	            "wgmma.mma_async.sync.aligned.m64n64k16.f32.bf16.bf16 " PF_ACC32 ",{%32,%33,%34,%35},%36,p,%38,%39,%40;\n}\n"
547	            : PF_OUT32(acc, O)
548	            : "r"(P[kb*4+0]),"r"(P[kb*4+1]),"r"(P[kb*4+2]),"r"(P[kb*4+3]),"l"(dB),"r"(1),"n"(1),"n"(1),"n"(1));
549	    }
550	}
551	// One 128-col PV output box: (CN/16)x m64n128k16 wgmma into acc[O..O+63]. A=P (registers, K-major),
552	// B=V (MN-major, transB=1). Reads dv[0,64) from baseV and dv[64,128) via the descriptor LBO (== the
553	// dv-block stride == CN*128 bytes == +BOX), so ONE wgmma covers 128 dv -> half the PV wgmma of the 2x
554	// m64n64 form (matches FA3's 8x HGMMA.64x128x16 .tnspB, denser tensor feeding). voffR is already a
555	// canonical MN-major GMMA layout (verified vs cute make_gmma_desc<Major::MN>). No fence/commit here.
556	template <typename T, int O, int N, int CN>
557	__device__ __forceinline__ void pv_box128_body(float (&acc)[N], const uint32_t (&P)[CN/4], uint64_t baseV) {
558	#pragma unroll
559	    for (int kb = 0; kb < CN / 16; ++kb) {
560	        uint64_t dB = desc_add(baseV, (uint32_t)v_doff(kb));
561	        if constexpr (is_f16<T>())
562	            asm volatile(
563	            "{\n.reg .pred p;\n setp.ne.b32 p, %69, 0;\n"
564	            "wgmma.mma_async.sync.aligned.m64n128k16.f32.f16.f16 " PF_ACC64 ",{%64,%65,%66,%67},%68,p,%70,%71,%72;\n}\n"
565	            : PF_OUT64O(acc, O)
566	            : "r"(P[kb*4+0]),"r"(P[kb*4+1]),"r"(P[kb*4+2]),"r"(P[kb*4+3]),"l"(dB),"r"(1),"n"(1),"n"(1),"n"(1));
567	        else
568	            asm volatile(
569	            "{\n.reg .pred p;\n setp.ne.b32 p, %69, 0;\n"
570	            "wgmma.mma_async.sync.aligned.m64n128k16.f32.bf16.bf16 " PF_ACC64 ",{%64,%65,%66,%67},%68,p,%70,%71,%72;\n}\n"
571	            : PF_OUT64O(acc, O)
572	            : "r"(P[kb*4+0]),"r"(P[kb*4+1]),"r"(P[kb*4+2]),"r"(P[kb*4+3]),"l"(dB),"r"(1),"n"(1),"n"(1),"n"(1));
573	    }
574	}
575	template <int N>
576	__device__ __forceinline__ void rescale_o_g(float (&acc_o)[N], const float* sc) {
577	#pragma unroll
578	    for (int c = 0; c < N / 4; ++c) {
579	        acc_o[c*4+0] *= sc[0]; acc_o[c*4+1] *= sc[0];
580	        acc_o[c*4+2] *= sc[1]; acc_o[c*4+3] *= sc[1];
581	    }
582	}
583	// PV: emit ceil(HDVsm/64) 64-col boxes. V box b starts CN*64 elems (one CN-row col-block) apart;
584	// the descriptor leading-byte-offset spans that same col-block (CN*64*2 = CN*128 bytes).
585	template <typename T, int HDV, int CN>
586	__device__ __forceinline__ void pv_boxes(float (&acc_o)[HDV/2], const uint32_t (&P)[CN/4], uint32_t sV_base) {
587	    constexpr uint32_t LBO = (uint32_t)(CN * 128), BOX = (uint32_t)(CN * 128);
588	    // ONE wgmma group for the whole PV: single fence, all boxes, single commit -> wgmma_wait1 (after the
589	    // next QK) leaves the FULL PV in flight to overlap the softmax (FA3-style QK/PV pipeline). Emit
590	    // HDV/128 m64n128 boxes (each spans 2 dv-blocks: dv[128b,128b+64) at sV_base+2b*BOX, dv[128b+64,+128)
591	    // via the descriptor LBO==dv-block stride==+BOX), + a trailing m64n64 box for HDV%128==64. This halves
592	    // the PV wgmma vs the old 2x-m64n64 form (matches FA3's 8x HGMMA.64x128x16 .tnspB) -> denser tensor
593	    // feeding, fewer issue slots stolen from softmax. Accumulator reg->(dv,row) mapping is identical.
594	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
595	    if constexpr (HDV >= 128) pv_box128_body<T, 0,  HDV/2, CN>(acc_o, P, make_smem_desc(sV_base + 0*BOX, LBO, SW_V_SBO, 1));
596	    if constexpr (HDV >= 256) pv_box128_body<T, 64, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base + 2*BOX, LBO, SW_V_SBO, 1));
597	    if constexpr (HDV == 64)  pv_box64_body <T, 0,  HDV/2, CN>(acc_o, P, make_smem_desc(sV_base + 0*BOX, LBO, SW_V_SBO, 1));
598	    if constexpr (HDV == 192) pv_box64_body <T, 64, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base + 2*BOX, LBO, SW_V_SBO, 1));
599	    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
600	}
601	// First K-block: QK only (s = Q.K^T), HD-generic.
602	template <typename T, int HDt, int CN, int CM = CTA_M>
603	__device__ __forceinline__ void qk_gemm_g(float (&s)[CN/2], uint32_t sQ_wg, uint32_t sK_base) {
604	    uint64_t baseA = make_smem_desc(sQ_wg,   SW_QK_LBO, SW_QK_SBO, 1);
605	    uint64_t baseB = make_smem_desc(sK_base, SW_QK_LBO, SW_QK_SBO, 1);
606	    qk_batch_g<T, HDt, CN, CM>(s, baseA, baseB, 0);
607	    asm volatile("wgmma.wait_group.sync.aligned 0;\n" ::: "memory");
608	    wg_fence_c(s);
609	}
610	// Fused QK (next block) + rescale O + PV (current block), HD/HDV/CN-generic. acc_o has HDV/2 regs.
611	template <typename T, int HD, int HDV, int CN, int CM = CTA_M>
612	__device__ __forceinline__ void qk_rs_pv_g(float (&s)[CN/2], float (&acc_o)[HDV/2], const uint32_t (&P)[CN/4],
613	                                           uint32_t sQ_wg, uint32_t sK_base, uint32_t sV_base, const float* sc) {
614	    uint64_t baseA = make_smem_desc(sQ_wg,   SW_QK_LBO, SW_QK_SBO, 1);
615	    uint64_t baseB = make_smem_desc(sK_base, SW_QK_LBO, SW_QK_SBO, 1);
616	    qk_batch_g<T, HD, CN, CM>(s, baseA, baseB, 0);
617	    rescale_o_g(acc_o, sc);
618	    pv_boxes<T, HDV, CN>(acc_o, P, sV_base);
619	}
620	// Fused QK (next block) + PV (current block) with NO O-rescale between the two wgmma issues -- matches
621	// FA3's schedule (issue QK(i+1) and PV(i) back-to-back, both left in flight, then rescale O AFTER PV via
622	// rescale_o_g). Inserting the 64-ALU rescale between the issues (qk_rs_pv_g) delays PV and cuts the
623	// QK||PV tensor overlap; deferring it recovers tensor-pipe utilization. acc_o has HDV/2 regs.
624	template <typename T, int HD, int HDV, int CN, int CM = CTA_M>
625	__device__ __forceinline__ void qk_pv_g(float (&s)[CN/2], float (&acc_o)[HDV/2], const uint32_t (&P)[CN/4],
626	                                        uint32_t sQ_wg, uint32_t sK_base, uint32_t sV_base) {
627	    uint64_t baseA = make_smem_desc(sQ_wg,   SW_QK_LBO, SW_QK_SBO, 1);
628	    uint64_t baseB = make_smem_desc(sK_base, SW_QK_LBO, SW_QK_SBO, 1);
629	    qk_batch_g<T, HD, CN, CM>(s, baseA, baseB, 0);
630	    pv_boxes<T, HDV, CN>(acc_o, P, sV_base);
631	}
632	// Final PV (last block, after the loop), HDV/CN-generic.
633	template <typename T, int HDV, int CN>
634	__device__ __forceinline__ void pv_final_g(float (&acc_o)[HDV/2], const uint32_t (&P)[CN/4], uint32_t sV_base) {
635	    pv_boxes<T, HDV, CN>(acc_o, P, sV_base);
636	    asm volatile("wgmma.wait_group.sync.aligned 0;\n" ::: "memory");
637	    wg_fence_c(acc_o);
638	    wg_fence_a(P);
639	}
