641	// ============================ native fp8 (e4m3) prefill path ============================
642	// QK and PV both run on the fp8 tensor core (2x bf16 throughput). The f32 accumulator layout for
643	// m64n128k32.e4m3 is identical to the bf16 m64n128k16 one, so softmax/mask/epilogue are unchanged.
644	// fp8 1-byte 128B swizzle: 128 fp8 = one 128B row; the 16-byte (16-fp8) chunk is swizzled by row&7.
645	// For hd128/CTA_N=128 every operand tile (Q,K,Vt,P) is a [128-row,128-col] K-major fp8 tile. The
646	// whole recipe (koff8 + LBO16/SBO1024/lt=1 + k32 step=kb*32 + V-transpose + P-in-smem SS-PV) is
647	// validated bit-exact vs a CPU fp8 GEMM in kernels/fp8_probe.cu.
648	// Row-count-generic fp8 128B swizzle: the col-block (c>=128) stride is 128*ROWS (# rows in the tile).
649	// ROWS=CTA_N reproduces the original koff8 exactly (and for HD<=128, c<128 so the col-block term is 0,
650	// making ROWS irrelevant -- byte-identical to the old koff8 on every existing hd128 path).
651	template <int ROWS> __device__ __forceinline__ int koff8R(int row, int c) {
652	    return (c >> 7) * (128 * ROWS) + row * 128 + ((c & 127) ^ ((row & 7) << 4));
653	}
654	__device__ __forceinline__ int koff8(int row, int c) { return koff8R<CTA_N>(row, c); }
655	constexpr uint32_t SW8_LBO = 16, SW8_SBO = 1024;
656	__device__ __forceinline__ void wg_barrier(int id) {
657	    asm volatile("bar.sync %0, 128;\n" :: "r"(id) : "memory");
658	}
659	// FA3 warp-scheduler ping-pong primitives (mainloop_fwd_sm90_tma_gmma_ws.hpp). A named barrier with
660	// an explicit arrival count: one consumer WG `bar.sync`s it (contributes its 128 threads + blocks)
661	// while the other WG `bar.arrive`s it (contributes 128, no block). With cnt = 256 the syncing WG
662	// unblocks only once the other WG arrives -> the two consumer WGs alternate their wgmma-issue phase
663	// by one step, so while WG_a runs softmax on the SFU, WG_b feeds the tensor core (and vice-versa).
664	__device__ __forceinline__ void nb_sync(int id, int cnt) {
665	    asm volatile("bar.sync %0, %1;\n" :: "r"(id), "r"(cnt) : "memory");
666	}
667	__device__ __forceinline__ void nb_arrive(int id, int cnt) {
668	    asm volatile("bar.arrive %0, %1;\n" :: "r"(id), "r"(cnt) : "memory");
669	}
670	// QK: s[CN/2] = Q.K^T (m64n{CN}k32 e4m3 SS over HD; first k-block overwrites, rest accumulate). The Q(A)
671	// tile has CTA_M rows, the K(B) tile CN rows, so once HD spans >1 128-col block their per-k-block descriptor
672	// strides differ (128*CTA_M vs 128*CN) -- mirrors the bf16 qk_doffR<CM> vs qk_doffR<CN>. CN=CTA_N (hd<=128,
673	// kb<4) keeps offA==offB==kb*32 (col-block term 0) -> byte-identical to before. Validated in fp8_probe256.cu.
674	template <int HDt, int CN = CTA_N>
675	__device__ __forceinline__ void qk_fp8_ss(float (&s)[CN/2], uint32_t sQ_wg, uint32_t sK_base) {
676	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
677	#pragma unroll
678	    for (int kb = 0; kb < HDt / 32; ++kb) {
679	        uint32_t offA = (uint32_t)((kb & 3) * 32 + (kb >> 2) * (128 * CTA_M));
680	        uint32_t offB = (uint32_t)((kb & 3) * 32 + (kb >> 2) * (128 * CN));
681	        uint64_t dA = make_smem_desc(sQ_wg + offA, SW8_LBO, SW8_SBO, 1);
682	        uint64_t dB = make_smem_desc(sK_base + offB, SW8_LBO, SW8_SBO, 1);
683	        int scaleD = (kb == 0) ? 0 : 1;
684	        if constexpr (CN == 128)
685	            asm volatile(
686	            "{\n.reg .pred p;\n setp.ne.b32 p, %66, 0;\n"
687	            "wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " PF_ACC64 ",%64,%65,p,%67,%68;\n}\n"
688	            : PF_OUT64(s) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1));
689	        else
690	            asm volatile(
691	            "{\n.reg .pred p;\n setp.ne.b32 p, %34, 0;\n"
692	            "wgmma.mma_async.sync.aligned.m64n64k32.f32.e4m3.e4m3 " PF_ACC32 ",%32,%33,p,%35,%36;\n}\n"
693	            : PF_OUT32(s, 0) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1));
694	    }
695	    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
696	}
697	// PV: acc_o[HDV/2] += P.V (e4m3 SS over CTA_N keys; A=P[q][key], B=Vt[dv][key]). m64n128 for HDV=128,
698	// m64n64 for HDV=64 (hd64 fp8 decode -- acc_o[32]). The Vt koff8 layout + SW8 descriptor are HDV-agnostic
699	// (only the dv-row count differs), so n is the only change. Always accumulates (running online output).
700	// For HDV>128 the output is tiled into HDV/128 m64n128 boxes: box b reads Vt rows [128b,128b+128) at
701	// sV_base + b*(128*128) and accumulates acc_o[64b..64b+63]. acc_o is the persistent online output ->
702	// scaleD=1 always. CN keys -> CN/32 k-blocks. CN=CTA_N=128,HDV=128 reduces to the old single-box loop.
703	template <int HDV, int CN = CTA_N>
704	__device__ __forceinline__ void pv_fp8_ss(float (&acc_o)[HDV/2], uint32_t sP_wg, uint32_t sV_base) {
705	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
706	    constexpr int NBOX = (HDV > 128) ? (HDV / 128) : 1;
707	#pragma unroll
708	    for (int box = 0; box < NBOX; ++box) {
709	        const uint32_t vboff = (uint32_t)(box * (128 * 128));
710	#pragma unroll
711	        for (int kb = 0; kb < CN / 32; ++kb) {
712	            uint32_t off = (uint32_t)(kb * 32);
713	            uint64_t dA = make_smem_desc(sP_wg + off, SW8_LBO, SW8_SBO, 1);
714	            uint64_t dB = make_smem_desc(sV_base + vboff + off, SW8_LBO, SW8_SBO, 1);
715	            if constexpr (HDV >= 128)
716	                asm volatile(
717	                "{\n.reg .pred p;\n setp.ne.b32 p, %66, 0;\n"
718	                "wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " PF_ACC64 ",%64,%65,p,%67,%68;\n}\n"
719	                : PF_OUT64O(acc_o, box * 64) : "l"(dA),"l"(dB),"r"(1),"n"(1),"n"(1));
720	            else
721	                asm volatile(
722	                "{\n.reg .pred p;\n setp.ne.b32 p, %34, 0;\n"
723	                "wgmma.mma_async.sync.aligned.m64n64k32.f32.e4m3.e4m3 " PF_ACC32 ",%32,%33,p,%35,%36;\n}\n"
724	                : PF_OUT32(acc_o, 0) : "l"(dA),"l"(dB),"r"(1),"n"(1),"n"(1));
725	        }
726	    }
727	    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
728	}
729	// FA3 register-source P (MmaPV_is_RS): build the fp8 A-operand registers from the f32 softmax
730	// probabilities s[64] (C-accumulator layout) WITHOUT the smem scatter+barrier round-trip. Pack each
731	// c-group's 4 f32 ((p,r2) combined, convert_layout_acc_Aregs order) -> P16[c], then permute_Aregs_fp8
732	// (quad __shfl + byte_perm) fixes the register layout to the wgmma A operand. Validated bit-exact vs
733	// the SS path in kernels/fp8_probe.cu (PV-RS). tg=lane&3, group=lane>>2.
734	template <int CN = CTA_N>
735	__device__ __forceinline__ void build_P_rs_fp8(const float (&s)[CN/2], uint32_t (&P16)[CN/8], int tg, int group) {
736	    constexpr int NC = CN / 8;   // c-groups (16 for CN=128, 8 for CN=64); per-pair permute count = NC/2
737	#pragma unroll
738	    for (int c = 0; c < NC; ++c) {
739	        __nv_fp8_e4m3 e0(s[c*4+0]), e1(s[c*4+1]), e2(s[c*4+2]), e3(s[c*4+3]);
740	        P16[c] = (uint32_t)e0.__x | ((uint32_t)e1.__x << 8) | ((uint32_t)e2.__x << 16) | ((uint32_t)e3.__x << 24);
741	    }
742	    const bool lane_03 = (tg == 0 || tg == 3);
743	    const int sel_up = lane_03 ? 0x5410 : 0x1054, sel_lo = lane_03 ? 0x7632 : 0x3276;
744	    const int up = (tg == 0) ? 0 : (tg == 1) ? 3 : (tg == 2) ? 1 : 2;   // upper_map[tg]
745	    const int src_hi = group * 4 + up, src_lo = group * 4 + (up ^ 1);
746	#pragma unroll
747	    for (int u = 0; u < NC / 2; ++u) {
748	        uint32_t upper = P16[2*u + 0], lower = P16[2*u + 1];
749	        uint32_t upper0 = lane_03 ? upper : lower;
750	        uint32_t lower0 = lane_03 ? lower : upper;
751	        upper0 = __shfl_sync(0xffffffffu, upper0, src_hi, 32);
752	        lower0 = __shfl_sync(0xffffffffu, lower0, src_lo, 32);
753	        P16[2*u + 0] = __byte_perm(upper0, lower0, sel_up);
754	        P16[2*u + 1] = __byte_perm(upper0, lower0, sel_lo);
755	    }
756	}
757	// PV with P in REGISTERS (RS A operand): acc_o += P.V over CN keys, A = P16[4kb..4kb+3] per k-block,
758	// B = Vt[dv][key] (smem descriptor). No smem-P scatter/barrier -> enables the QK(i+1)/PV(i) pipeline.
759	// HDV>128 is tiled into HDV/128 m64n128 boxes (box b reads Vt rows [128b,128b+128) at sV_base+b*128*128
760	// and accumulates acc_o[64b..64b+63]); box b reuses the SAME P16 (P is dv-independent). CN k-blocks =
761	// CN/32, P16 has CN/8 regs. HDV<128 -> single m64n64 box (acc_o[32]). Always accumulates (scaleD=1).
762	template <int HDV, int CN = CTA_N>
763	__device__ __forceinline__ void pv_fp8_rs(float (&acc_o)[HDV/2], const uint32_t (&P16)[CN/8], uint32_t sV_base) {
764	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
765	    constexpr int NBOX = (HDV > 128) ? (HDV / 128) : 1;
766	#pragma unroll
767	    for (int box = 0; box < NBOX; ++box) {
768	        const uint32_t vboff = (uint32_t)(box * (128 * 128));
769	#pragma unroll
770	        for (int kb = 0; kb < CN / 32; ++kb) {
771	            uint32_t off = (uint32_t)(kb * 32);
772	            uint64_t dB = make_smem_desc(sV_base + vboff + off, SW8_LBO, SW8_SBO, 1);
773	            if constexpr (HDV >= 128)
774	                asm volatile(
775	                "{\n.reg .pred p;\n setp.ne.b32 p, %68, 0;\n"
776	                "wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " PF_ACC64 ",{%64,%65,%66,%67},%69,p,%70,%71;\n}\n"
777	                : PF_OUT64O(acc_o, box * 64)
778	                : "r"(P16[kb*4+0]),"r"(P16[kb*4+1]),"r"(P16[kb*4+2]),"r"(P16[kb*4+3]),
779	                  "r"(1),"l"(dB),"n"(1),"n"(1));

